const input = $input.first().json;
const body = input.body || input;
const jobId = body.jobId || ('tags-' + Date.now() + '-' + Math.random().toString(36).substr(2, 8));
const clientName = body.clientName;
const sdrData = body.sdrData || body.sdr;
const callbackUrl = body.callbackUrl || null;
const adobeCredentials = body.adobeCredentials || null;

if (!clientName || !sdrData) throw new Error('Missing required fields: clientName, sdrData');
if (!sdrData.evars || !sdrData.events) {
  throw new Error('sdrData must contain evars and events for Tags creation');
}

console.log('=== Tags Job ===');
console.log('Job ID:', jobId);
console.log('Client:', clientName);
console.log('eVars:', sdrData.evars.length, 'Events:', sdrData.events.length);

return [{ json: { jobId, clientName, sdrData, callbackUrl, adobeCredentials, jobStartedAt: new Date().toISOString() } }];

const input = $('Validate Tags Input').first().json;
const adobeCredentials = input.adobeCredentials || null;
// Emulate the shape that Prepare Rules (Dynamic) expects from Parse SDR Output
return [{ json: {
  success: true,
  clientName: input.clientName,
  sdr: input.sdrData,
  adobeCredentials: adobeCredentials,
  stats: {
    evars: input.sdrData.evars?.length || 0,
    props: input.sdrData.props?.length || 0,
    events: input.sdrData.events?.length || 0,
  },
  validation: { coverage_pct: 100, warnings: [] },
} }];

// Parse extension info and prepare config
const input = $input.first().json["data"];
const { data: arrInput } = JSON.parse(input);
const tokenData = $('Merge Token & Credentials').first().json;

const existingExtensions = (arrInput || []).map(ext => ({
  id: ext.id,
  name: ext.attributes?.name,
  delegateDescriptorId: ext.attributes?.delegate_descriptor_id,
  extensionPackage: ext.relationships.extension_package.data.id
}));

const coreExt = existingExtensions.find(ext =>
  ext.delegateDescriptorId?.includes('core::') || ext.name?.toLowerCase() === 'core'
);

const alloyExt = existingExtensions.find(ext =>
  ext.delegateDescriptorId?.includes('alloy') ||
  ext.delegateDescriptorId?.includes('adobe-cloud-connector') ||
  ext.name?.toLowerCase().includes('web sdk') ||
  ext.name?.toLowerCase().includes('alloy')
);

return [{
  json: {
    accessToken: tokenData.access_token,
    credentials: tokenData.credentials,
    existingExtensions,
    coreExtensionId: coreExt?.id,
    alloyExtensionId: alloyExt?.id,
    alloyInstalled: !!alloyExt
  }
}];

// Extract all unique %dl.xxx% references from launchPayload and generate Data Element list
const input = $input.first().json;
const sdrOutput = $('Parse SDR Output').first().json;
const launchPayloadContent = sdrOutput.sdr?.launchPayload;

function extractDlRefs(obj, refs) {
  if (typeof obj === 'string') {
    const matches = obj.match(/%dl\.[^%]+%/g) || [];
    matches.forEach(m => refs.add(m));
  } else if (Array.isArray(obj)) {
    obj.forEach(item => extractDlRefs(item, refs));
  } else if (obj && typeof obj === 'object') {
    Object.values(obj).forEach(v => extractDlRefs(v, refs));
  }
}

const allRefs = new Set();

if (launchPayloadContent) {
  let lp;
  try {
    lp = typeof launchPayloadContent === 'string' ? JSON.parse(launchPayloadContent) : launchPayloadContent;
  } catch(e) {
    console.warn('Failed to parse launchPayload for Data Element extraction:', e.message);
    lp = null;
  }
  if (lp?.rules) extractDlRefs(lp.rules, allRefs);
}

if (allRefs.size === 0) {
  console.log('No %dl.xxx% references found — skipping Data Element creation');
  // Return single dummy item so Loop Data Elements immediately goes to done branch
  return [{ json: { ...input, dataElement: null, skipDataElements: true, totalDataElements: 0 } }];
}

// %dl.foo.bar% → { name: 'dl.foo.bar', path: 'digitalData.foo.bar' }
const dataElements = [...allRefs].map(ref => {
  const inner = ref.replace(/%/g, '');
  const path = inner.replace(/^dl\./, 'digitalData.');
  return { name: inner, path, ref };
});

console.log(`[Data Elements] Found ${dataElements.length} unique references to create`);

return dataElements.map(de => ({
  json: { ...input, dataElement: de, skipDataElements: false, totalDataElements: dataElements.length }
}));

// Dynamically load rules from sdrData.launchPayload (if present) or generate from evars/events
const input = $input.first().json;

const sdrOutput = $('Parse SDR Output').first().json;
const launchPayloadContent = sdrOutput.sdr?.launchPayload;

if (launchPayloadContent) {
  // ── Path A: pre-built launchPayload rules ──────────────────────────────
  let launchConfig;
  try {
    launchConfig = typeof launchPayloadContent === 'string'
      ? JSON.parse(launchPayloadContent)
      : launchPayloadContent;
  } catch (e) {
    throw new Error('Failed to parse launchPayload JSON: ' + e.message);
  }

  const rules = launchConfig.rules || [];
  if (rules.length === 0) {
    console.warn('⚠️  launchPayload contains no rules');
    return [];
  }

  console.log(`[Path A] Preparing ${rules.length} pre-built rules from launchPayload`);

  return rules.map((rule, idx) => ({
    json: {
      ...input,
      ruleIndex: idx,
      ruleName: rule.name,
      ruleEvents: rule.events || [],
      ruleConditions: rule.conditions || [],
      ruleActions: rule.actions || [],
      totalRules: rules.length
    }
  }));

} else {
  // ── Path B: fallback — auto-generate rules from sdrData evars/events ──
  console.log('[Path B] No launchPayload — auto-generating rules from SDR evars/events');

  const sdr = sdrOutput.sdr || {};
  const events = sdr.events || [];

  if (events.length === 0) {
    console.warn('⚠️  No events found in sdrData — cannot generate rules');
    return [];
  }

  // Generate one Adobe Launch rule per event:
  // Trigger: core::events::dom-ready
  // Action:  adobe-alloy::actions::send-event (Web SDK sendEvent)
  const rules = events.map((evt, idx) => {
    const eventLabel = evt.event_name || evt.event || `Event ${idx + 1}`;
    const eventKey   = (evt.event || '').replace(/\s*\[.*?\]\s*/g, '').trim().toLowerCase().replace(/\s+/g, '_');

    return {
      name: `Track - ${eventLabel}`,
      events: [{
        modulePath: 'core/src/lib/events/domReady.js',
        settings: {}
      }],
      conditions: [],
      actions: [{
        modulePath: 'adobe-alloy/src/lib/actions/sendEvent.js',
        settings: {
          xdm: `%${eventKey}_xdm%`,
          type: `web.${eventKey}`
        }
      }]
    };
  });

  console.log(`[Path B] Generated ${rules.length} rules from ${events.length} SDR events`);

  return rules.map((rule, idx) => ({
    json: {
      ...input,
      ruleIndex: idx,
      ruleName: rule.name,
      ruleEvents: rule.events,
      ruleConditions: rule.conditions,
      ruleActions: rule.actions,
      totalRules: rules.length,
      autoGenerated: true
    }
  }));
}

// Extract rule ID and prepare rule components (Events, Conditions, Actions)
const ruleResult = $input.first().json;
const prevData = $('Loop Rules').first().json;

const ruleObj = JSON.parse(ruleResult.data);
const ruleId = ruleObj?.data.id;

const descriptorMapping = {
  "adobe-alloy/src/lib/actions/sendEvent.js": "adobe-alloy::actions::send-event",
  "core/src/lib/events/click.js": "core::events::click",
  "core/src/lib/events/libraryLoaded.js": "core::events::library-loaded",
  "core/src/lib/events/domReady.js": "core::events::dom-ready",
  "core/src/lib/events/customEvent.js": "core::events::custom-event",
  "core/src/lib/conditions/customCode.js": "core::conditions::custom-code"
};

// Fallback: type/name → modulePath (for legacy launchPayload format)
const typeToModulePath = {
  'dom-ready':      'core/src/lib/events/domReady.js',
  'page-load':      'core/src/lib/events/domReady.js',
  'library-loaded': 'core/src/lib/events/libraryLoaded.js',
  'click':          'core/src/lib/events/click.js',
  'custom':         'core/src/lib/events/customEvent.js',
  'sendEvent':      'adobe-alloy/src/lib/actions/sendEvent.js'
};

function resolveModulePath(component) {
  if (component.modulePath) return component.modulePath;
  if (component.type) return typeToModulePath[component.type] || 'core/src/lib/events/customEvent.js';
  return 'core/src/lib/events/customEvent.js';
}

function resolveSettings(component) {
  if (component.settings) return component.settings;
  if (component.type === 'custom' && component.name) return { type: component.name };
  if (component.type === 'sendEvent' && component.xdm) return { xdm: component.xdm };
  return {};
}

if (!ruleId) {
  throw new Error(`Rule creation failed (${prevData.ruleName}): ${JSON.stringify(ruleResult)}`);
}

const components = [];

// Events
(prevData.ruleEvents || []).forEach((evt, idx) => {
  const modulePath = resolveModulePath(evt);
  components.push({
    componentType: 'events',
    order: idx,
    modulePath,
    extensionDescriptorId: descriptorMapping[modulePath] || modulePath,
    extensionId: prevData.coreExtensionId,
    settings: JSON.stringify(resolveSettings(evt)),
    name: `Event ${idx + 1}`
  });
});

// Conditions
(prevData.ruleConditions || []).forEach((cond, idx) => {
  const modulePath = resolveModulePath(cond);
  components.push({
    componentType: 'conditions',
    order: idx,
    modulePath,
    extensionDescriptorId: descriptorMapping[modulePath] || modulePath,
    extensionId: prevData.coreExtensionId,
    settings: JSON.stringify(resolveSettings(cond)),
    name: `Condition ${idx + 1}`,
    negate: false
  });
});

// Actions
(prevData.ruleActions || []).forEach((act, idx) => {
  const modulePath = resolveModulePath(act);
  const isAlloy = modulePath.includes('alloy') || modulePath.includes('adobe-alloy') || modulePath.includes('adobe-alchemy');
  components.push({
    componentType: 'actions',
    order: idx,
    modulePath,
    extensionDescriptorId: descriptorMapping[modulePath] || modulePath,
    extensionId: isAlloy ? prevData.alloyExtensionId : prevData.coreExtensionId,
    settings: JSON.stringify(resolveSettings(act)),
    name: `Action ${idx + 1}`
  });
});

return components.map(comp => ({
  json: { ...prevData, ruleId, component: comp }
}));

const credentials = {
  accessToken: $('Merge Token & Credentials').first().json.access_token,
  apiKey: $('Merge Token & Credentials').first().json.credentials.API_KEY,
  imgOrg: $('Merge Token & Credentials').first().json.credentials.IMS_ORG
};

const ruleData = $('Create Rule').first().json;

return [{
  json: Object.assign(credentials, { data: ruleData.data })
}];

const items = $input.all();
const clientName = $('Validate Tags Input').first().json.clientName || 'Unknown';

return [{
  json: {
    success: true,
    clientName: clientName,
    message: 'Adobe Launch Rules & Data Elements deployed successfully',
    summary: {
      rulesCreated: items.length,
      componentsCreated: 'Events, Conditions, Actions included',
      dataElementsCreated: 'All %dl.xxx% references created as JavaScript Variable Data Elements',
    },
    nextSteps: [
      '1. Verify created rules and data elements in Adobe Launch UI',
      '2. Create Library and build to Development environment',
      '3. QA test all tracking events',
      '4. Promote to Production after sign-off',
    ],
  }
}];
